# Initially generated by GitHub Copilot.
"""Bot edit: replace קו״כ-אם (trivial k/q) with מ:קו״כ-אם-2.

Old format: {{קו״כ-אם|pointed-ketiv|2=<source-indicator>=pointed-qere}}
New format: {{מ:קו״כ-אם-2|pointed-ketiv|unpointed-ketiv|pointed-qere|מקורות=<source-indicator>}}

Edge cases (logged as warnings, old template left in place):
  - Param 1 is an unsupported inner template
  - Param 2 has an atypical value (qere sub-string contains space or '(')

Special case (param 1 is a מ:דחי call):
  - Param 1 is {{מ:דחי|pketiv-1d|pketiv-2d}}; the whole מ:דחי call
    becomes param 1 of the new template, and the unpointed ketiv is
    derived from the first arg of מ:דחי (pketiv-1d, the single-deḥi form).

Special case (param 1 is a מ:קמץ call):
  - Param 1 is {{מ:קמץ|ד=pketiv|ס=pketiv-alt}}; the whole מ:קמץ call
    becomes param 1 of the new template, and the unpointed ketiv is
    derived from the ד= arg of מ:קמץ.

Special case (param 1 ends with מ:לגרמיה-2):
  - Param 1 is {{...|pketiv{{ל}}|2=source=pqere{{ל}}}}; the ל is passed through
    to both ketiv and qere slots of the new template.

Special case (omit מקורות= entirely):
  - Param 2 starts with 'קרי=' (policy-based, no manuscript source)

Warnings are accumulated in _warnings and retrieved via get_warnings().
The caller is responsible for writing them to a file.

See ws_bot_edit_history.md and MAM-basics#55.
"""

from functools import partial

from mb_cmn import hebrew_accents as hac
from mb_cmn import ws_tmpl1 as wtp1
from mb_cmn.my_utils import dv_dispatch
from mb_cmn.my_utils import dv_map
from mb_cmn.my_utils import sl_map
from mb_cmn.my_utils import sum_of_map
from mb_cmn.shrink import shrink
from mb_misc import hebrew_letter_words as hlw
from ws import ws_fmt_2_back_to_wikitext as btw
from ws import ws_get_bk_in_both_fmts as wsin

# Module-level context set per chapter during edit_page_text.
_ctx = {"bk39id": None, "he_chnu": None}
_warnings = []

_OLD_TMPL_NAME = "קו״כ-אם"
_NEW_TMPL_NAME = "מ:קו״כ-אם-2"

_ATYPICAL = object()  # sentinel for _parse_param2
_COMPLEX = object()  # sentinel for _parse_param1
_LEGARMEH = "מ:לגרמיה-2"
_ALLOWED_TAIL_TMPLS = (_LEGARMEH, "מ:קמץ")


def _parse_param1(el):
    """Parse param 1 element. Returns (ketiv_wt_el, pointed_ketiv_str, dexi_arg2) or _COMPLEX.

    ketiv_wt_el is the list to use directly as a template element in new_els.
    pointed_ketiv_str is the plain string from which the unpointed ketiv
    is derived (always pketiv-1d, the single-deḥi form).
    dexi_arg2 is None for the plain-string case, or the second arg string
    of the מ:דחי call (used to synthesize the qere מ:דחי call).

    Handled cases:
      - el is a plain-string singleton: [s] -> ([s], s, None)
      - el is a singleton מ:דחי call with two plain-string args:
        [{'stmpl': 'מ:דחי|a|b'}] -> ([dexi_tmpl], a, b)
      - el is a singleton מ:קמץ call with named args ד= and ס=:
        [{'stmpl': 'מ:קמץ|ד=a|ס=b'}] -> ([qamats_tmpl], a, None)
      - el is a plain string followed by מ:לגרמיה-2:
        [s, legar_tmpl] -> ([s, legar_tmpl], s, None)
    """
    if len(el) == 1 and isinstance(el[0], str):
        s = el[0]
        return el, s, None
    if (
        len(el) == 2
        and isinstance(el[0], str)
        and wtp1.is_template_with_name(el[1], _LEGARMEH)
    ):
        return el, el[0], None
    if (
        len(el) == 1
        and wtp1.is_template_with_name(el[0], "מ:קמץ")
        and wtp1.template_len(el[0]) == 3
    ):
        qamats_tmpl = el[0]
        dalet_el = wtp1.named_template_element(qamats_tmpl, 1, "ד")
        if len(dalet_el) == 1 and isinstance(dalet_el[0], str):
            return el, dalet_el[0], None
    if (
        len(el) == 1
        and wtp1.is_template_with_name(el[0], "מ:דחי")
        and wtp1.template_len(el[0]) == 3
    ):
        dexi_tmpl = el[0]
        dexi_arg1_el = wtp1.template_element(dexi_tmpl, 1)
        dexi_arg2_el = wtp1.template_element(dexi_tmpl, 2)
        if (
            len(dexi_arg1_el) == 1
            and isinstance(dexi_arg1_el[0], str)
            and len(dexi_arg2_el) == 1
            and isinstance(dexi_arg2_el[0], str)
        ):
            a1, a2 = dexi_arg1_el[0], dexi_arg2_el[0]
            _assert_dexi_counts(a1, a2)
            return el, a1, a2
    return _COMPLEX


def _assert_dexi_counts(arg1, arg2):
    """Assert arg1 has exactly 1 deḥi mark and arg2 has exactly 2."""
    n1 = arg1.count(hac.DEX)
    n2 = arg2.count(hac.DEX)
    assert n1 == 1, f"expected 1 deḥi in arg1, got {n1}: {arg1!r}"
    assert n2 == 2, f"expected 2 deḥi in arg2, got {n2}: {arg2!r}"


def _insert_yod(s):
    """Insert yod before the final vav of s."""
    assert s[-1] == "ו", f"expected final vav, got {s[-1]!r} in {s!r}"
    return s[:-1] + "י" + s[-1]


def _parse_param2(s):
    """Parse param 2 string. Returns (source, qere) or _ATYPICAL.

    source is None for the policy-based case (no manuscript source).
    """
    eq_idx = s.find("=")
    if eq_idx == -1:
        return _ATYPICAL
    source_key = s[:eq_idx]
    qere = s[eq_idx + 1 :]
    # Atypical: qere contains a space or '(' (e.g. Eccl 10:10 free-text note)
    if " " in qere or "(" in qere:
        return _ATYPICAL
    # Policy-based (no manuscript source): source_key is exactly "קרי"
    if source_key == "קרי":
        return None, qere
    return source_key, qere


def get_warnings():
    """Return accumulated warning entries (list of dicts)."""
    return list(_warnings)


def _warn(reason, old_tmpl):
    _warnings.append(
        {
            "bk39id": _ctx["bk39id"],
            "he_chnu": _ctx["he_chnu"],
            "reason": reason,
            "old_tmpl": old_tmpl,
        }
    )


def _transform_kq_triv(tmpl):
    """Transform one קו״כ-אם template to מ:קו״כ-אם-2."""
    assert wtp1.template_len(tmpl) == 3

    # Param 1: pointed ketiv — plain string or מ:דחי call
    param1_el = wtp1.template_element(tmpl, 1)
    param1_result = _parse_param1(param1_el)
    if param1_result is _COMPLEX:
        _warn("complex-param-1", tmpl)
        return [tmpl]
    ketiv_wt_el, pointed_ketiv_str, dexi_arg2 = param1_result

    # Param 2: named param "2=<source-indicator>=<qere>[{{מ:לגרמיה-2}}]"
    param2_el = wtp1.named_template_element(tmpl, 2, "2")
    if not (param2_el and isinstance(param2_el[0], str)):
        _warn("complex-param-2", tmpl)
        return [tmpl]
    param2_head = param2_el[0]
    param2_tail = list(param2_el[1:])
    if not all(
        wtp1.is_template_with_name_in(x, _ALLOWED_TAIL_TMPLS) for x in param2_tail
    ):
        _warn("complex-param-2", tmpl)
        return [tmpl]

    parse_result = _parse_param2(param2_head)
    if parse_result is _ATYPICAL:
        _warn("atypical-param-2", tmpl)
        return [tmpl]
    source, pointed_qere = parse_result

    unpointed_ketiv = hlw.letters_and_maqafs(pointed_ketiv_str)

    if dexi_arg2 is None:
        qere_wt_el = [pointed_qere, *param2_tail]
    else:
        qere_arg1 = _insert_yod(pointed_ketiv_str)
        assert (
            qere_arg1 == pointed_qere
        ), f"expected qere {pointed_qere!r} == {qere_arg1!r}"
        qere_arg2 = _insert_yod(dexi_arg2)
        qere_wt_el = [wtp1.mktmpl([["מ:דחי"], [qere_arg1], [qere_arg2]])]

    new_els = [
        [_NEW_TMPL_NAME],
        ketiv_wt_el,
        [unpointed_ketiv],
        qere_wt_el,
    ]
    if source is not None:
        new_els.append([f"מקורות={source}"])
    return [wtp1.mktmpl(new_els)]


def _pass_thru(val):
    return val


def _pass_thru_as_singleton(val):
    return [val]


def _edit_wtseq(wandlers, wtseq):
    return shrink(sum_of_map((_edit_wtel, wandlers), wtseq))


def _edit_wtel(wandlers, wtel):
    if isinstance(wtel, str):
        return wandlers["string"](wtel)
    if wtp1.is_abtag(wtel):
        return [wtel]
    return _edit_tmpl_call(wandlers, wtel)


def _edit_tmpl_call(wandlers, tmpl):
    if wandler := wandlers.get(wtp1.template_name(tmpl)):
        return wandler(tmpl)
    return _recurse_on_args(_get_wandlers, tmpl)


def _recurse_on_args(get_wandlers_fn, tmpl):
    tmpl_els_in = wtp1.template_elements(tmpl)
    assert isinstance(tmpl_els_in, list)
    wandlers = get_wandlers_fn()
    tmpl_args_out = sl_map((_edit_wtseq, wandlers), tmpl_els_in[1:])
    tmpl_els_out = [tmpl_els_in[0], *tmpl_args_out]
    return [wtp1.mktmpl(tmpl_els_out)]


def _get_wandlers():
    return _WANDLERS


def _edit_a_chap_body(vandlers, chap_body):
    return dv_map((_edit_a_plb_verse, vandlers), chap_body)


def _edit_a_plb_verse(vandlers, plb_verse):
    return dv_dispatch(vandlers, plb_verse)


_WANDLERS = {
    "string": _pass_thru_as_singleton,
    _OLD_TMPL_NAME: _transform_kq_triv,
}

_VANDLERS = {
    "prefix": _pass_thru,
    "location": _pass_thru,
    "verse-body": partial(_edit_wtseq, _WANDLERS),
}

_CANDLERS = {
    "ws-chap-noinclude-header": _pass_thru,
    "ws-chap-body": partial(_edit_a_chap_body, _VANDLERS),
    "ws-chap-good-ending": _pass_thru,
    "ws-chap-noinclude-footer": _pass_thru,
    "ws-chap-category": _pass_thru,
}


def edit_cif2(he_chnu, cif2):
    """Transform cif2 AST: replace קו״כ-אם with מ:קו״כ-אם-2."""
    out_cif2 = dv_dispatch(_CANDLERS, cif2)
    return out_cif2, btw.big_str(he_chnu, out_cif2)


def edit_page_text(bk39id, he_chnu, page_text):
    """Transform raw page text: replace קו״כ-אם with מ:קו״כ-אם-2."""
    _ctx["bk39id"] = bk39id
    _ctx["he_chnu"] = he_chnu
    cif2 = wsin.get_chap_in_fmt_2(page_text.splitlines())
    _out_cif2, big_str = edit_cif2(he_chnu, cif2)
    return big_str
